#!/usr/bin/env node
// Builds a real on-disk postern.repo/v1 repo (fixtures/dist/index.json +
// index.json.sig) from the keypair generated by gen-keys.mjs. Run
// `node scripts/gen-keys.mjs` first. This produces the exact static-host
// layout A-repo-client.md §1 specifies:
//   index.json
//   index.json.sig   (raw 64 bytes, NOT base64)
import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { buildSignedIndex } from "../lib/build-index.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const fixturesDir = join(here, "..", "fixtures");
const keyPath = join(fixturesDir, "repo-key.json");
const distDir = join(fixturesDir, "dist");

if (!existsSync(keyPath)) {
  console.error("No fixtures/repo-key.json found — run `node scripts/gen-keys.mjs` first.");
  process.exit(1);
}
const { publicKey, privateKey } = JSON.parse(readFileSync(keyPath, "utf8"));

const { indexBytes, sigBytes } = buildSignedIndex({
  privateKeyB64: privateKey,
  publicKeyB64: publicKey,
  timestamp: Math.floor(Date.now() / 1000),
});

mkdirSync(distDir, { recursive: true });
writeFileSync(join(distDir, "index.json"), indexBytes);
writeFileSync(join(distDir, "index.json.sig"), sigBytes); // raw 64 bytes, binary

console.log("Wrote a real signed postern.repo/v1 repo to fixtures/dist/:");
console.log("  index.json      ", indexBytes.length, "bytes");
console.log("  index.json.sig  ", sigBytes.length, "bytes (must be 64)");
console.log("Pin this key to verify it:", publicKey);
